WITH flattened AS (SELECT base.id, base.customer_id, base.coupon_codes, item.product_id, item.qty, item.price FROM carts base LATERAL VIEW OUTER EXPLODE(base.items) e AS item) SELECT CASE WHEN product_id >= 10 THEN 'LARGE' ELSE 'SMALL' END AS product_id_tier, COUNT(*) AS event_count, APPROX_PERCENTILE(product_id, 0.95) AS product_id_p95, SUM(price) AS total_price, MAX(qty) AS max_qty FROM flattened GROUP BY CASE WHEN product_id >= 10 THEN 'LARGE' ELSE 'SMALL' END HAVING MAX(qty) > 0;
